export const chemMaterials: AuthoredMaterial[] = [
  { id: "neet-chemistry-basic-concepts-mole-m01", topicId: "neet-chemistry-basic-concepts-mole", title: "Basic Concepts & the Mole", content: `A **mole** is **6.022 × 10²³** (Avogadro's number) of particles and equals the substance's molar mass in grams. **Moles = mass / molar mass = number of particles / Nₐ = volume of gas / 22.4 L** (at STP). **Empirical formula** gives the simplest whole-number ratio of atoms; the **molecular formula** is a whole-number multiple of it. **Stoichiometry** uses balanced equations to relate reactant and product amounts; the **limiting reagent** is completely consumed and determines the maximum product. Concentration terms: **molarity (mol/L, temperature-dependent)** and **molality (mol/kg, temperature-independent)**.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-chemistry-states-of-matter-m01", topicId: "neet-chemistry-states-of-matter", title: "States of Matter", content: `The **ideal gas equation** PV = nRT combines Boyle's (P ∝ 1/V at constant T), Charles's (V ∝ T at constant P), and Avogadro's laws. **Dalton's law**: total pressure = sum of partial pressures. **Graham's law**: rate of diffusion ∝ 1/√(molar mass). Real gases deviate from ideality at **high pressure and low temperature**; the **van der Waals equation** adds corrections for molecular volume (b) and attraction (a). Gases can be liquefied below their **critical temperature**. Liquids show **surface tension** and **viscosity**, both decreasing with temperature.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-chemistry-redox-reactions-m01", topicId: "neet-chemistry-redox-reactions", title: "Redox Reactions", content: `**Oxidation** is loss of electrons (increase in oxidation number); **reduction** is gain of electrons (decrease). Remember **OIL RIG** (Oxidation Is Loss, Reduction Is Gain). A **reducing agent** is itself oxidised; an **oxidising agent** is itself reduced. **Oxidation numbers** follow rules (O = −2, H = +1, sum = charge). Redox reactions are balanced by the **ion-electron (half-reaction)** method. In a **disproportionation** reaction, the same element is simultaneously oxidised and reduced (e.g., Cl₂ + water). Redox underlies electrochemistry, combustion, corrosion, and respiration.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-chemistry-solutions-m01", topicId: "neet-chemistry-solutions", title: "Solutions & Colligative Properties", content: `Concentration is expressed as **molarity, molality, mole fraction, and ppm**. **Henry's law**: gas solubility ∝ partial pressure. **Raoult's law**: the vapour pressure of a component ∝ its mole fraction; ideal solutions obey it. **Colligative properties** depend only on the number of solute particles: **relative lowering of vapour pressure, boiling-point elevation (ΔTb = Kb·m), freezing-point depression (ΔTf = Kf·m), and osmotic pressure (π = CRT)**. The **van 't Hoff factor (i)** accounts for dissociation or association of the solute. These properties are used to find molar masses.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-chemistry-electrochemistry-m01", topicId: "neet-chemistry-electrochemistry", title: "Electrochemistry", content: `A **galvanic cell** converts chemical energy to electrical energy: oxidation at the **anode (−)**, reduction at the **cathode (+)**. **E°cell = E°cathode − E°anode**; a positive value means a spontaneous reaction (**ΔG° = −nFE°cell**). The **Nernst equation** E = E° − (0.059/n)log Q (298 K) gives concentration dependence. **Faraday's laws**: mass deposited ∝ charge (Q = It). **Conductivity** decreases and **molar conductivity** increases on dilution (Kohlrausch's law of independent ion migration). An **electrolytic cell** uses electrical energy to drive a non-spontaneous reaction.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-chemistry-chemical-kinetics-m01", topicId: "neet-chemistry-chemical-kinetics", title: "Chemical Kinetics", content: `**Rate = k[A]^m[B]^n**; the **order** (m+n) is determined experimentally, not from stoichiometry. **First-order** reactions have a concentration-independent **half-life (t½ = 0.693/k)** and k in s⁻¹; **zero-order** rate is constant. The **Arrhenius equation** k = A·e^(−Ea/RT) shows rate increasing with temperature (roughly doubling per 10 °C). A **catalyst** lowers the activation energy, providing an alternate path, without changing ΔG or the equilibrium. **Collision theory** requires molecules to collide with sufficient energy (≥ Ea) and proper orientation.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-chemistry-surface-chemistry-m01", topicId: "neet-chemistry-surface-chemistry", title: "Surface Chemistry", content: `**Adsorption** is accumulation at a surface (physisorption — weak van der Waals, reversible; chemisorption — strong, specific). **Catalysis** may be homogeneous or heterogeneous; **enzymes** are highly specific biocatalysts. **Colloids** (particle size 1–1000 nm) are intermediate between true solutions and suspensions, classified by phase (sol, gel, emulsion, aerosol) and by affinity (lyophilic/lyophobic). Colloids show the **Tyndall effect** (scattering of light) and **Brownian motion**; they are purified by dialysis and coagulated by adding electrolytes (**Hardy–Schulze rule**: higher-charge ions coagulate more effectively).`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-chemistry-s-block-elements-m01", topicId: "neet-chemistry-s-block-elements", title: "s-Block Elements", content: `Group 1 (**alkali metals**: Li, Na, K…) and Group 2 (**alkaline earth metals**: Be, Mg, Ca…) have ns¹ and ns² configurations. They are highly reactive, strong reducing agents, and form ionic compounds. Reactivity **increases down the group** as ionisation energy falls. They impart characteristic **flame colours** (Na — yellow, K — lilac, Ca — brick-red). **Diagonal relationships** (Li–Mg, Be–Al) arise from similar charge/size ratios. Important compounds: NaOH, Na₂CO₃ (washing soda), NaHCO₃ (baking soda), CaO (quicklime), CaSO₄·½H₂O (plaster of Paris).`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-chemistry-p-block-elements-m01", topicId: "neet-chemistry-p-block-elements", title: "p-Block Elements", content: `The p-block (Groups 13–18) shows the widest range of properties — metals, metalloids, and non-metals. **Inert pair effect** stabilises lower oxidation states down a group. Group trends: **13** (B to Tl; B is a metalloid), **14** (C, Si; catenation strongest in carbon), **15** (N₂ is inert; NH₃, HNO₃), **16** (O, S; H₂SO₄), **17** (halogens — most electronegative, strong oxidisers; reactivity F > Cl > Br > I), **18** (noble gases — stable, full octet; Xe forms fluorides). Anomalous behaviour of the first element in each group is due to its small size and absence of d-orbitals.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-chemistry-d-f-block-elements-m01", topicId: "neet-chemistry-d-f-block-elements", title: "d- & f-Block Elements", content: `**Transition (d-block) elements** have partially filled d-orbitals and show **variable oxidation states, coloured ions (d–d transitions), paramagnetism, catalytic activity, and complex/alloy formation**. Atomic radii are similar across a period. The **lanthanoid contraction** (steady decrease in size across the 4f series) makes second- and third-row transition metals similar in size. **f-block** elements are the lanthanoids (4f) and actinoids (5f, all radioactive). KMnO₄ and K₂Cr₂O₇ are important oxidising agents. Zn, Cd, Hg (d¹⁰) are not typical transition metals.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-chemistry-metallurgy-m01", topicId: "neet-chemistry-metallurgy", title: "General Principles of Metallurgy", content: `Extraction of a metal from its ore involves **concentration** (froth flotation for sulphides, magnetic separation, leaching), **conversion to oxide** (roasting for sulphides, calcination for carbonates/hydroxides), **reduction** to the metal, and **refining**. Reduction may be by carbon/CO (blast furnace for iron), a more reactive metal (**thermite/aluminothermite** for Cr, Mn), or **electrolysis** for very reactive metals (Na, Al by the Hall–Héroult process). **Ellingham diagrams** show which reducing agent works at a given temperature. Refining methods include distillation, liquation, electrolytic refining, and zone refining (for ultra-pure Si/Ge).`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-chemistry-amines-m01", topicId: "neet-chemistry-amines", title: "Amines & Nitrogen Compounds", content: `**Amines** (R–NH₂) are derivatives of ammonia, classed as **primary, secondary, or tertiary**. They are **basic** (lone pair on N); in the gas phase basicity is 3° > 2° > 1° > NH₃, while in water solvation effects usually make 2°/1° comparably basic and **aromatic amines (aniline) much weaker** (lone pair delocalised into the ring). Amines are prepared by reduction of nitro compounds/nitriles, **Gabriel synthesis** (1° only), and **Hoffmann bromamide** (amide → amine with one fewer carbon). **Diazonium salts** (Ar–N₂⁺, from aniline + HNO₂ at 0–5 °C) are versatile intermediates in dye and substitution chemistry.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-chemistry-polymers-m01", topicId: "neet-chemistry-polymers", title: "Polymers", content: `**Polymers** are macromolecules built from repeating **monomers**. By synthesis: **addition (chain-growth)** polymers form from unsaturated monomers (polythene, PVC, Teflon, polystyrene) and **condensation (step-growth)** polymers form with loss of a small molecule (nylon-6,6, terylene/dacron, bakelite). By source: natural (cellulose, rubber, proteins), semi-synthetic, and synthetic. **Elastomers** (rubber) have weak forces; **fibres** (nylon) have strong hydrogen bonding; **thermoplastics** soften on heating, **thermosetting** plastics (bakelite) set permanently. **Biodegradable** polymers (PHBV, nylon-2-nylon-6) address plastic pollution.`, estimatedReadTime: 2, orderIndex: 0 },
  { id: "neet-chemistry-chemistry-everyday-life-m01", topicId: "neet-chemistry-chemistry-everyday-life", title: "Chemistry in Everyday Life", content: `**Drugs** act on molecular targets: **antacids** (ranitidine) reduce stomach acid; **antihistamines** counter allergies; **antibiotics** (penicillin — bactericidal) kill/inhibit microbes; **analgesics** (aspirin — also antiplatelet) relieve pain; **antiseptics** (Dettol) are applied to living tissue while **disinfectants** (phenol) are used on non-living surfaces. **Food additives** include artificial sweeteners (aspartame, saccharin) and preservatives (sodium benzoate). **Soaps** (sodium salts of fatty acids) fail in hard water; **detergents** work in hard water. Cleansing action arises from **micelle** formation around grease.`, estimatedReadTime: 2, orderIndex: 0 }
];

